import sys
from collections import defaultdict

q = int(sys.stdin.readline())
assignments = {}
history = []
priority_count = defaultdict(int)

for _ in range(q):
    operation = sys.stdin.readline().strip().split()
    if operation[0] == "set":
        ai, xi = operation[1], int(operation[2])
        if ai in assignments:
            old_xi = assignments[ai]
            priority_count[old_xi] -= 1
        assignments[ai] = xi
        priority_count[xi] += 1
        history.append(("set", ai, xi))
    elif operation[0] == "remove":
        ai = operation[1]
        if ai in assignments:
            xi = assignments[ai]
            del assignments[ai]
            priority_count[xi] -= 1
            history.append(("remove", ai))
    elif operation[0] == "query":
        ai = operation[1]
        if ai not in assignments:
            print(-1)
        else:
            xi = assignments[ai]
            count = sum(priority_count[p] for p in priority_count if p < xi)
            print(count)
    elif operation[0] == "undo":
        di = int(operation[1])
        for _ in range(di):
            if history:
                op, *args = history.pop()
                if op == "set":
                    ai, xi = args
                    if priority_count[xi] == 1:
                        del priority_count[xi]
                    else:
                        priority_count[xi] -= 1
                    if ai in assignments and assignments[ai] == xi:
                        del assignments[ai]
                    if len(args) == 3:
                        old_ai, old_xi = args
                        assignments[old_ai] = old_xi
                        priority_count[old_xi] += 1
                elif op == "remove":
                    ai = args[0]
                    xi = assignments[ai]
                    priority_count[xi] += 1
sys.stdout.flush()
